<script>
$(document).ready(function() {
    $(document).on('click', '.btn-view-trx', function(e) {
        e.preventDefault();
        var noPesanan = $(this).attr('data-pesanan');
        $('#modalNoPesananText').text(noPesanan);
        $('#modalTrxContent').html('<div class="text-center" style="padding: 30px;"><i class="fa fa-spinner fa-spin fa-2x"></i><br>Memuat data transaksi...</div>');
        $('#modalTransaction').modal('show');

        $.ajax({
            url: BASE_URL + 'administrator/spin_histories/get_transaction_detail',
            type: 'GET',
            data: { no_pesanan: noPesanan },
            success: function(response) {
                $('#modalTrxContent').html(response);
            },
            error: function() {
                $('#modalTrxContent').html('<div class="alert alert-danger"><i class="fa fa-warning"></i> Gagal memuat data transaksi. Silakan coba kembali.</div>');
            }
        });
    });
});
</script>
